<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { apiGet,apiPatch } from '../api/client';import KpiGrid from '../components/KpiGrid.vue';import PageHeader from '../components/PageHeader.vue';import type { FeedItem } from '../types/admin'
import { useAuthStore } from '../stores/auth';const auth=useAuthStore()
const items=ref<FeedItem[]>([]);const loading=ref(true);const status=ref('')
const filtered=computed(()=>items.value.filter(x=>!status.value||x.status===status.value));const kpis=computed(()=>[{label:'待审',value:items.value.filter(x=>x.status==='pending').length,delta:'需处理',warn:true},{label:'已发布',value:items.value.filter(x=>x.status==='published').length,delta:'正常展示'},{label:'举报总数',value:items.value.reduce((s,x)=>s+x.reportCount,0),delta:'数据库汇总'},{label:'已下架',value:items.value.filter(x=>x.status==='offline').length,delta:'已处理'}])
async function load(){loading.value=true;try{items.value=await apiGet<FeedItem[]>('/admin/feeds')}finally{loading.value=false}}
async function setStatus(tableRow:unknown,next:'published'|'offline'){const row=tableRow as FeedItem;await ElMessageBox.confirm(`确认${next==='published'?'通过':'下架'}该内容？`,'内容审核',{type:'warning'});await apiPatch(`/admin/feeds/${row.id}/status`,{status:next});ElMessage.success('审核结果已保存');await load()}
onMounted(load)
</script>
<template><PageHeader title="评论与举报" group="用户与内容" description="审核小程序 UGC 内容与举报"><el-button :loading="loading" @click="load">刷新</el-button></PageHeader><KpiGrid :items="kpis" :loading="loading"/><section class="panel"><div class="panel__toolbar"><el-select v-model="status" clearable placeholder="全部状态" style="width:150px"><el-option label="待审核" value="pending"/><el-option label="已发布" value="published"/><el-option label="已下架" value="offline"/></el-select><span class="muted">{{filtered.length}} 条内容</span></div><el-table :data="filtered" v-loading="loading"><el-table-column label="作者" width="130"><template #default="{row}"><strong>{{row.author.nickname}}</strong></template></el-table-column><el-table-column prop="content" label="内容" min-width="300" show-overflow-tooltip/><el-table-column label="类型" width="90"><template #default="{row}"><el-tag effect="plain">{{row.type==='video'?'视频':'图文'}}</el-tag></template></el-table-column><el-table-column label="关联路线" min-width="220"><template #default="{row}">{{row.discovery?.title||'—'}}</template></el-table-column><el-table-column prop="reportCount" label="举报" width="80"/><el-table-column label="发布时间" width="170"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN',{hour12:false})}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='published'?'success':row.status==='pending'?'warning':'info'">{{row.status==='published'?'已发布':row.status==='pending'?'待审核':'已下架'}}</el-tag></template></el-table-column><el-table-column v-if="auth.hasPermission('feed:audit')" label="操作" width="170"><template #default="{row}"><div class="table-actions"><el-button v-if="row.status==='pending'" size="small" type="success" @click="setStatus(row,'published')">通过</el-button><el-button v-if="row.status!=='offline'" size="small" type="danger" plain @click="setStatus(row,'offline')">下架</el-button></div></template></el-table-column></el-table></section></template>
